export const api = async (path, options = {}) => {
  const response = await fetch(`/api/v1${path}`, { credentials: 'include', headers: { 'content-type': 'application/json', ...(options.headers || {}) }, ...options });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) { const error = new Error(data?.error?.message || `Request failed (${response.status})`); error.status = response.status; error.code = data?.error?.code; throw error; }
  return data;
};
export const apiV3 = async (path, options = {}) => {
  const response = await fetch(`/api/v3${path}`, { credentials: 'include', headers: { 'content-type': 'application/json', ...(options.headers || {}) }, ...options });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) { const error = new Error(data?.error?.message || `Request failed (${response.status})`); error.status = response.status; error.code = data?.error?.code; throw error; }
  return data;
};

const NAV = [
  { key: 'Today', label: 'Today', icon: '⌂' },
  { key: 'People', label: 'People', icon: '♙' },
  { key: 'Content', label: 'Content', icon: '▣' },
  { key: 'Productions', label: 'Productions', icon: '▤' },
  { key: 'Growth', label: 'Growth', icon: '▥' },
  { key: 'Money', label: 'Money', icon: '▱' }
];
const number = value => Number.isFinite(Number(value)) ? Number(value) : 0;
const formatNumber = value => new Intl.NumberFormat('en-US').format(number(value));
const formatDate = value => value ? new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(value)) : '—';
const formatTime = value => value ? new Intl.DateTimeFormat('en-US', { hour: 'numeric', minute: '2-digit' }).format(new Date(value)) : '—';
const titleCase = value => String(value || '').replaceAll('_', ' ').replace(/\b\w/g, character => character.toUpperCase());
const initials = value => String(value || 'F').split(/\s+/).map(part => part[0]).join('').slice(0, 2).toUpperCase();
const isTestRecord = item => /acceptance[-_\s]*test|test[-_\s]*(?:only|data|record)/i.test([item?.id, item?.legacy_id, item?.title, item?.slug, item?.contract_number, item?.full_name, item?.display_name, item?.action, item?.event_type, item?.source].filter(Boolean).join(' '));
const summaryValue = (summary, keys) => {
  if (!summary || typeof summary !== 'object') return null;
  for (const key of keys) if (typeof summary[key] === 'string' && summary[key].trim()) return summary[key].trim();
  return null;
};
const humanActivity = entry => {
  if (!entry || isTestRecord(entry)) return null;
  const action = String(entry.action || '').toLowerCase();
  const map = [
    [/application\.(?:submitted|created)|applicant\.(?:submitted|created)/, 'New applicant received', ['full_name', 'display_name', 'name']],
    [/contract\.(?:assigned|issued)/, 'Contract assigned', ['performer_name', 'display_name', 'title', 'contract_number']],
    [/contract\.(?:signed|performer_signed)/, 'Contract signed', ['performer_name', 'display_name', 'title', 'contract_number']],
    [/(?:company|contract)\.(?:countersigned|company_signed|fully_executed)/, 'Contract completed', ['performer_name', 'display_name', 'title', 'contract_number']],
    [/(?:video|catalogue)\.(?:published|released)/, 'Video published', ['title', 'display_name', 'name']],
    [/(?:identity|verification)\.(?:approved|verified)/, 'Performer verification approved', ['display_name', 'full_name', 'name']],
    [/media\.(?:uploaded|approved|published)/, 'New performer media', ['display_name', 'full_name', 'name', 'title']],
    [/production\.(?:created|scheduled|ready)/, 'Production updated', ['title', 'display_name', 'name']]
  ];
  const matched = map.find(([pattern]) => pattern.test(action));
  if (!matched) return null;
  const [, label, keys] = matched;
  const subject = summaryValue(entry.after_summary, keys) || summaryValue(entry.before_summary, keys);
  return { ...entry, label, subject: subject && !isTestRecord({ title: subject }) ? subject : null };
};

