function Login({ onSuccess }) {
  const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const submit = async event => { event.preventDefault(); setBusy(true); setError(''); try { await api('/auth/login', { method: 'POST', body: JSON.stringify({ email, password }) }); onSuccess(); } catch (e) { setError(e.message); } finally { setBusy(false); } };
  return <main className="approved-login"><div className="approved-login-logo">FLESH<span>LAB</span></div><section><p className="approved-eyebrow">FLESHLAB OPERATIONS</p><h1>Welcome back.</h1><p>Sign in to continue to your workspace.</p><form onSubmit={submit}><label>Email<input type="email" value={email} onChange={event => setEmail(event.target.value)} required /></label><label>Password<input type="password" value={password} onChange={event => setPassword(event.target.value)} required /></label>{error && <div className="approved-error">{error}</div>}<button className="approved-primary" disabled={busy}>{busy ? 'Signing in…' : 'Sign in'}</button></form></section></main>;
}

function Sidebar({ section, navigate, user, logout }) { return <aside className="approved-sidebar"><a className="approved-logo" href="/admin/"><span>FLESH</span>LAB</a><nav>{NAV.map(item => <button className={section === item.key ? 'active' : ''} key={item.key} onClick={() => navigate(item.key)}><i>{item.icon}</i><span>{item.label}</span></button>)}</nav><div className="approved-side-bottom"><button className={section === 'Settings' ? 'active' : ''} onClick={() => navigate('Settings')}><i>⚙</i><span>Settings</span></button><div className="approved-profile"><div className="approved-avatar">{initials(user?.email)}</div><div><strong>Eric</strong><span>Owner</span></div><b>›</b></div><button className="approved-logout" onClick={logout}>Sign out</button></div></aside>; }
function Topbar({ navigate, user }) { const [open, setOpen] = useState(false); return <header className="approved-topbar"><div className="approved-search"><span>⌕</span><input placeholder="Search performers, videos, productions…" aria-label="Search" /></div><button className="approved-bell" aria-label="Notifications">♧<b>4</b></button><div className="approved-new-wrap"><button className="approved-new" onClick={() => setOpen(value => !value)}><span>＋</span> New <b>⌄</b></button>{open && <div className="approved-new-menu"><strong>Start something new</strong><button onClick={() => { setOpen(false); navigate('People'); }}>Add performer</button><button onClick={() => { setOpen(false); navigate('Productions'); }}>New production</button><button onClick={() => { setOpen(false); navigate('Content'); }}>Upload video</button><button onClick={() => { setOpen(false); navigate('Money'); }}>Create product</button></div>}</div><div className="approved-top-avatar">{initials(user?.email)}</div></header>; }
function Eyebrow({ children }) { return <p className="approved-eyebrow">{children}</p>; }
function ArrowButton({ children, onClick }) { return <button className="approved-arrow" onClick={onClick} aria-label={children}>{children}</button>; }
function Media({ src, fallback, className = '' }) { return <div className={`approved-media ${className} ${src ? '' : 'approved-media-fallback'}`}>{src ? <img src={src} alt="" /> : <span>{initials(fallback)}</span>}</div>; }
function PerformerMedia({ performer, className = '' }) {
  const performerId = normalizePerformerId(performer?.legacy_id);
  const initial = performer?.profile_image_url || '';
  const [src, setSrc] = useState(initial);
  useEffect(() => {
    let active = true;
    setSrc(initial);
    if (!performerId || initial) return () => { active = false; };
    (async () => {
      try {
        const detail = await apiV3(`/admin/performers/${encodeURIComponent(performerId)}`);
        const record = detail?.performer || {};
        if (record.profile_image_url) { if (active) setSrc(record.profile_image_url); return; }
        const creator = record.creators?.[0];
        if (!creator?.id || !record.profile_media_asset_id) return;
        const view = await apiV3(`/admin/creators/records/${encodeURIComponent(creator.id)}/media/${encodeURIComponent(record.profile_media_asset_id)}/view`, { method: 'POST', body: '{}' });
        if (active && view?.view_url) setSrc(view.view_url);
      } catch { /* Missing/private media remains a quiet placeholder. */ }
    })();
    return () => { active = false; };
  }, [performerId, initial]);
  return <Media src={src} fallback={performer?.display_name} className={className} />;
}
