function LoyalFansProviderStatus() {
  const [state,setState]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[cursor,setCursor]=useState(null),[summary,setSummary]=useState(null);
  const refresh=async()=>{try{setState(await apiV3('/admin/commerce/loyalfans/status'));setError('');}catch(e){setError(e.message);}};
  useEffect(()=>{refresh();},[]);
  const run=async path=>{setBusy(true);try{const reconciliation=path.endsWith('/reconcile');const result=await apiV3(path,{method:'POST',body:JSON.stringify(reconciliation?{cursor}:{})});if(reconciliation){setCursor(result.next_cursor);setSummary(result);await refresh();}else setState(result);setError('');}catch(e){setError(e.message);}finally{setBusy(false);}};
  return <div className="approved-card"><div className="approved-card-title"><h2>LoyalFans creator provider</h2><em className={state?.status==='CONNECTED'?'approved-status-green':'approved-status-amber'}>{state?.status||'LOADING'}</em></div><p className="approved-muted">Connection status only. Purchase Bridge: NOT READY until complete authenticated comment pagination and final transaction evidence are confirmed. Rotate the dedicated creator credential in server secrets, restart the API, then test the connection. Credentials are never shown here.</p>{error&&<p className="approved-notice">{error}</p>}{summary&&<p className="approved-muted">Examined {summary.examined} orders. {summary.pending_review} need review; {summary.provider_error} had provider errors. {summary.next_cursor?'More orders remain.':'Batch complete.'}</p>}<div className="approved-card-actions"><button type="button" disabled={busy} onClick={refresh}>Refresh status</button><button type="button" disabled={busy} onClick={()=>run('/admin/commerce/loyalfans/probe')}>Test connection</button><button type="button" disabled={busy} onClick={()=>run('/admin/commerce/loyalfans/reconcile')}>Reconcile purchases</button></div></div>;
}
