export function ApprovedAdminApp() {
  const params = new URLSearchParams(window.location.search); const preview = params.get('preview') === '1' && (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1' || window.location.protocol === 'file:'); const sectionAliases = { Performers: 'People', Creator: 'People', Contracts: 'People', Catalogue: 'Content', Production: 'Productions', Commerce: 'Money' }; const requestedSection = params.get('section'); const mappedSection = sectionAliases[requestedSection] || requestedSection; const initialSection = ['Today', 'People', 'Content', 'Productions', 'Growth', 'Money', 'Settings'].includes(mappedSection) ? mappedSection : 'Today'; const selectedFromUrl = normalizePerformerId(params.get('performerId') || params.get('performer_id')); const initialPerformerTab = normalizePerformerTab(params.get('performerTab') || params.get('performer_tab'));
  const [user, setUser] = useState(preview ? fixture.user : null); const [section, setSection] = useState(initialSection); const [data, setData] = useState(preview ? { ...fixture, activity: [], workspaces: {} } : { snapshots: {}, performers: { records: [] }, videos: { records: [] }, applications: { records: [] }, activity: [], workspaces: {} }); const [selectedId, setSelectedId] = useState(selectedFromUrl); const [detail, setDetail] = useState(null); const [error, setError] = useState(''); const [loading, setLoading] = useState(!preview);
  const load = async () => { if (preview) return; setLoading(true); try { const current = await api('/auth/me'); if (!['admin', 'staff'].includes(current.role)) throw new Error('This workspace is available to authorized FLESHLAB staff.'); const endpoints = ['/admin/catalogue/overview', '/admin/creators/overview', '/admin/production/overview', '/admin/growth/overview', '/admin/commerce/overview', '/admin/contracts/overview', '/admin/system/overview', '/admin/performers?limit=100', '/admin/catalogue/videos?limit=12', '/admin/creators/applications?status=submitted&limit=6', '/admin/commerce/plans?limit=24', '/admin/commerce/subscriptions?limit=24', '/admin/commerce/earnings?limit=24', '/admin/commerce/payouts?limit=24', '/admin/catalogue/collections', '/admin/growth/news?limit=12', '/admin/growth/campaigns?limit=24', '/admin/growth/attribution?limit=24', '/admin/growth/analytics', '/admin/growth/distribution?limit=24', '/admin/productions?limit=24', '/admin/production/schedule', '/admin/system/settings', '/admin/system/users?limit=50', '/admin/system/integrations', '/admin/system/flags', '/admin/catalogue/selectors']; const results = await Promise.allSettled(endpoints.map(path => apiV3(path))); const value = index => results[index].status === 'fulfilled' ? results[index].value : {}; setUser(current); setData({ snapshots: { catalogue: value(0), creators: value(1), production: value(2), growth: value(3), commerce: value(4), contracts: value(5), system: value(6), submissions: {} }, performers: value(7), videos: value(8), applications: value(9), activity: value(6).recent_audit || [], workspaces: { plans: value(10), subscriptions: value(11), earnings: value(12), payouts: value(13), collections: value(14), news: value(15), campaigns: value(16), attribution: value(17), analytics: value(18), distribution: value(19), productions: value(20), schedule: value(21), settings: value(22), users: value(23), integrations: value(24), flags: value(25), selectors: value(26) } }); } catch (e) { if (!/Authentication is required|Session is invalid/.test(e.message)) setError(e.message); } finally { setLoading(false); } };
  const loadDetail = async id => { const normalized = normalizePerformerId(id); if (!normalized) { setDetail(null); return; } if (preview) { setDetail({ performer: fixture.performers.records[0], creators: [], users: [], videos: [], productions: [], contracts: [], earnings: [] }); return; } setDetail(null); try { setDetail(await apiV3(`/admin/performers/${encodeURIComponent(normalized)}`)); } catch (failure) { setDetail({ error: failure.status === 404 || failure.code === 'PERFORMER_NOT_FOUND' ? 'not_found' : 'load' }); } };
  useEffect(() => { load(); }, []); useEffect(() => { loadDetail(selectedId); }, [selectedId]);
  const navigate = next => { setSection(next); setSelectedId(null); setDetail(null); const url = new URL(window.location.href); url.searchParams.set('section', next); url.searchParams.delete('performerId'); url.searchParams.delete('performer_id'); url.searchParams.delete('performerTab'); url.searchParams.delete('performer_tab'); window.history.replaceState({}, '', `${url.pathname}?${url.searchParams.toString()}`); };
  const openPerformer = id => { const normalized = normalizePerformerId(id); setSection('People'); setSelectedId(normalized); const url = new URL(window.location.href); url.searchParams.set('section', 'People'); url.searchParams.set('performerId', normalized); url.searchParams.delete('performer_id'); window.history.replaceState({}, '', `${url.pathname}?${url.searchParams.toString()}`); };
  const changePerformerTab = tab => { const url = new URL(window.location.href); url.searchParams.set('performerTab', tab); window.history.replaceState({}, '', `${url.pathname}?${url.searchParams.toString()}`); };
  const logout = async () => { if (!preview) await api('/auth/logout', { method: 'POST', body: '{}' }); setUser(null); };
  if (!user && loading) return <div className="approved-loading-screen"><span>FLESH</span>LAB <small>Loading workspace…</small></div>; if (!user && !loading) return <Login onSuccess={load} />; if (!user) return <Login onSuccess={load} />;
  const content = section === 'Today' ? <Today data={data} navigate={navigate} openPerformer={openPerformer} /> : section === 'People' && selectedId ? <PerformerWorkspace detail={detail} back={() => { setSelectedId(null); setDetail(null); const url = new URL(window.location.href); url.searchParams.delete('performerId'); url.searchParams.delete('performer_id'); url.searchParams.delete('performerTab'); window.history.replaceState({}, '', `${url.pathname}?${url.searchParams.toString()}`); }} navigate={navigate} initialTab={initialPerformerTab} onTabChange={changePerformerTab} /> : section === 'People' ? <People performers={data.performers} openPerformer={openPerformer} legacyAction={() => navigate('People')} /> : section === 'Content' ? <ContentWorkspace catalogue={data.snapshots.catalogue} videos={data.videos} collections={data.workspaces.collections} news={data.workspaces.news} navigate={navigate} /> : section === 'Productions' ? <ProductionsWorkspace production={data.snapshots.production} productions={data.workspaces.productions} schedule={data.workspaces.schedule} performers={data.performers} selectors={data.workspaces.selectors} refresh={load} /> : section === 'Growth' ? <GrowthWorkspace growth={data.snapshots.growth} campaigns={data.workspaces.campaigns} attribution={data.workspaces.attribution} analytics={data.workspaces.analytics} news={data.workspaces.news} distribution={data.workspaces.distribution} refresh={load} /> : section === 'Money' ? <MoneyWorkspace commerce={data.snapshots.commerce} plans={data.workspaces.plans} subscriptions={data.workspaces.subscriptions} earnings={data.workspaces.earnings} payouts={data.workspaces.payouts} refresh={load} /> : <SettingsWorkspace system={{ ...data.snapshots.system, settings: data.workspaces.settings, users: data.workspaces.users, integrations: data.workspaces.integrations, flags: data.workspaces.flags }} />;
  return <div className="approved-app"><Sidebar section={section} navigate={navigate} user={user} logout={logout} /><main className="approved-main"><Topbar navigate={navigate} user={user} />{error && <div className="approved-inline-error">{error}</div>}{content}</main></div>;
}
